235	function cleanOne(part: string): string | undefined {
236	  let s = part.trim().toLowerCase();
237	  s = s.replace(/^\d+(\.\d+)?\s*(ml|hr|day)\s+/i, "");
238	  const toks = s.split(/[\s,]+/).filter(Boolean);
239	  const kept: string[] = [];
240	  for (const t of toks) {
241	    if (/^\d/.test(t) || /^\d*\.?\d+(mg|mcg|ml|g|%)/.test(t)) break;
242	    if (FORM_WORDS.has(t)) break;
243	    if (t === "(" || t.startsWith("(")) break;
244	    kept.push(t.replace(/[^a-z\-]/g, ""));
245	  }
246	  let words = kept.filter(Boolean);
247	  // Brand names
248	  for (const w of words) if (BRANDS[w]) return BRANDS[w];
249	  const noSalt = words.filter((w) => !SALTS.has(w));
250	  if (noSalt.length > 0) words = noSalt;
251	  if (words.length === 0) return undefined;
252	  return words.join(" ");
253	}
254	
255	function ingredientOf(name: string): string | undefined {
256	  let n = name;
257	  const bracket = /\[([^\]]+)\]/.exec(n);
258	  n = n.replace(/\[[^\]]*\]/g, " ").trim();
259	  if (!n && bracket) n = bracket[1];
260	  const parts = n.split(/\s+\/\s+|\s+and\s+|-(?=[a-z]+\s+\d)/i);
261	  const ings: string[] = [];
262	  for (const p of parts) {
263	    const i = cleanOne(p);
264	    if (i && !ings.includes(i)) ings.push(i);
265	  }
266	  if (ings.length === 0) {
267	    if (bracket) {
268	      const b = bracket[1].trim().toLowerCase();
269	      if (BRANDS[b]) return BRANDS[b];
270	    }
271	    return undefined;
272	  }
273	  return ings.join(" / ");
274	}
