276	function isHospitalOnly(name: string): boolean {
277	  return /\b(intravenous|infusion|IVPB|IV piggyback|IV push|premix|in 0\.9 ?% sodium chloride|in dextrose)\b/i.test(name) ||
278	    /\bIV\b/.test(name);
279	}
