281	function mapDose(dose: any, drugName: string): MedicationRow["dose"] | undefined {
282	  if (!dose || typeof dose !== "object") return undefined;
283	  const v = dose.value;
284	  if (typeof v !== "number" || !isFinite(v) || v <= 0) return undefined;
285	  const u = String(dose.unit ?? "").trim().toLowerCase();
286	  if (u === "mg" || u === "milligram" || u === "milligrams") return { value: v, unit: "mg" };
287	  if (u === "mcg" || u === "ug" || u === "µg") return { value: v, unit: "mcg" };
288	  if (u === "ml") return { value: v, unit: "mL" };
289	  if (u === "unit" || u === "units" || u === "unt" || u === "[iu]" || u === "iu" || u === "u") return { value: v, unit: "units" };
290	  if (["tab", "tabs", "tablet", "tablets", "cap", "caps", "capsule", "capsules"].includes(u)) {
291	    // Express in mass when the name gives a single per-tablet strength.
292	    if (/\b(tablet|capsule|tab|cap)s?\b/i.test(drugName) && !/\//.test(drugName.replace(/\[[^\]]*\]/g, ""))) {
293	      const strengths = [...drugName.matchAll(/(\d+(?:\.\d+)?)\s*(MG|MCG)\b(?!\s*\/)/gi)];
294	      if (strengths.length === 1) {
295	        const amt = parseFloat(strengths[0][1]);
296	        const su = strengths[0][2].toLowerCase() === "mcg" ? "mcg" : "mg";
297	        if (isFinite(amt)) return { value: Math.round(amt * v * 1e6) / 1e6, unit: su };
298	      }
299	    }
300	    return { value: v, unit: "tablet" };
301	  }
302	  return undefined;
303	}
304	
305	function mapFreq(f: unknown, sig: unknown): MedicationRow["frequency"] | undefined {
306	  switch (f) {
307	    case "QD": return "QD";
308	    case "BID": return "BID";
309	    case "TID": return "TID";
310	    case "QHS": return "QHS";
311	    case "PRN": return "PRN";
312	    case "OTHER":
313	      if (typeof sig === "string" && /\b(once (a |per |every )?week|weekly|every week|q ?week)\b/i.test(sig)) return "QW";
314	      return "other";
315	  }
316	  return undefined;
317	}
