321	interface MedLine {
322	  row: MedicationRow;
323	  key: string;
324	  last: Ev;
325	  events: Ev[];
326	}
327	
328	function buildMedications(evs: Ev[]): { rows: MedicationRow[]; ingredientsByItem: Map<string, string[]> } {
329	  const lines: MedLine[] = [];
330	  const ingredientsByItem = new Map<string, string[]>();
331	  for (const [, events] of groupBy(evs, "med_id")) {
332	    const valid = events.filter((ev) => ["start", "change", "hold", "resume", "stop"].includes(ev.e.action));
333	    if (valid.length === 0) continue;
334	    const last = valid[valid.length - 1];
335	    const e = last.e;
336	    let drugName: string | undefined;
337	    for (let i = valid.length - 1; i >= 0 && !drugName; i--) drugName = str(valid[i].e.drug?.name);
338	    if (!drugName) continue;
339	    if (isHospitalOnly(drugName)) continue;
340	    const ingredient = ingredientOf(drugName);
341	
342	    let status: MedicationRow["status"];
343	    let sinceEv: Ev | undefined;
344	    if (e.action === "stop") {
345	      status = "stopped";
346	      sinceEv = last;
347	    } else if (e.action === "hold") {
348	      status = "held";
349	      // Start of the current run of holds.
350	      sinceEv = last;
351	      for (let i = valid.length - 1; i >= 0 && valid[i].e.action === "hold"; i--) sinceEv = valid[i];
352	    } else {
353	      status = "active";
354	      for (let i = valid.length - 1; i >= 0; i--) {
355	        if (valid[i].e.action === "start" || valid[i].e.action === "resume") { sinceEv = valid[i]; break; }
356	      }
357	    }
358	
359	    const row: MedicationRow = { drug_name: drugName, status, patient_reported: false, evidence: evidenceOf(valid) };
360	    if (ingredient) row.ingredient = ingredient;
361	    const since = sinceEv ? localDate(sinceEv.item.effective) : null;
362	    if (since) row.status_since = since;
363	    const dose = mapDose(e.dose, drugName);
364	    if (dose) row.dose = dose;
365	    const freq = mapFreq(e.frequency, e.sig);
366	    if (freq) row.frequency = freq;
367	    if (status === "stopped" && STOP_REASONS.has(e.stop_reason)) row.stop_reason = e.stop_reason;
368	    if (status !== "active") {
369	      const rt = str(e.reason_text);
370	      if (rt) row.status_reason_text = rt;
371	    }
372	    const sens = restrictedSens(valid);
373	    if (sens) row.sensitivity = sens;
374	
375	    for (const ev of valid) {
376	      if (!ingredient) continue;
377	      const arr = ingredientsByItem.get(ev.item.id) ?? [];
378	      if (!arr.includes(ingredient)) arr.push(ingredient);
379	      ingredientsByItem.set(ev.item.id, arr);
380	    }
381	    lines.push({ row, key: ingredient ?? "name:" + drugName.toLowerCase(), last, events: valid });
382	  }
383	
384	  // One row per ingredient: the line whose own latest event is latest.
385	  const best = new Map<string, MedLine>();
386	  for (const l of lines) {
387	    const cur = best.get(l.key);
388	    if (!cur || cmpEv(cur.last, l.last) < 0) best.set(l.key, l);
389	  }
390	  const rows = [...best.values()].sort((a, b) => cmpEv(a.last, b.last)).map((l) => l.row);
391	  return { rows, ingredientsByItem };
392	}
