398	function ckdStage(desc: string, icd: string | undefined): ProblemRow["ckd_stage"] | undefined {
399	  const d = desc.toLowerCase();
400	  let m = /\bstage\s*(1|2|3a|3b|4|5)\b/.exec(d) || /\bg(1|2|3a|3b|4|5)\b/.exec(d);
401	  if (m) return ("G" + m[1]) as ProblemRow["ckd_stage"];
402	  if (/\b(esrd|end[- ]stage)\b/.test(d)) return "G5";
403	  if (icd) {
404	    const c = icd.toUpperCase();
405	    if (c === "N18.1") return "G1";
406	    if (c === "N18.2") return "G2";
407	    if (c === "N18.31") return "G3a";
408	    if (c === "N18.32") return "G3b";
409	    if (c === "N18.4") return "G4";
410	    if (c === "N18.5" || c === "N18.6") return "G5";
411	  }
412	  return undefined;
413	}
