424	function icdSensitivity(icd: string | undefined): Sensitivity[] | undefined {
425	  if (!icd) return undefined;
426	  const c = icd.toUpperCase();
427	  if (/^F1\d/.test(c)) return ["substance-use"];
428	  if (/^F\d/.test(c)) return ["mental-health"];
429	  if (/^(B20|B97\.35|Z21|A5\d|A6[0-4])/.test(c)) return ["hiv-sti"];
430	  if (/^(O\d|Z3[0-9])/.test(c)) return ["sexual-reproductive-health"];
431	  return undefined;
432	}
