434	function mergeSens(a: Sensitivity[] | undefined, b: Sensitivity[] | undefined): Sensitivity[] | undefined {
435	  const s = [...(a ?? []), ...(b ?? [])];
436	  const out = s.filter((x, i) => s.indexOf(x) === i);
437	  return out.length ? out : undefined;
438	}
