444	  { re: /\bstatin\b/i, label: "statin", members: ["atorvastatin", "rosuvastatin", "simvastatin", "pravastatin", "lovastatin", "pitavastatin", "fluvastatin"] },
445	  { re: /\bglp-?1\b/i, label: "GLP-1 receptor agonist", members: ["semaglutide", "dulaglutide", "liraglutide", "exenatide", "tirzepatide"] },
446	  { re: /\bdpp-?4\b/i, label: "DPP-4 inhibitor", members: ["sitagliptin", "linagliptin", "saxagliptin", "alogliptin"] },
