453	const KNOWN_DRUGS: string[] = (() => {
454	  const s = new Set<string>(Object.values(BRANDS).filter((v) => !v.includes("/")));
455	  for (const c of DRUG_CLASSES) for (const m of c.members) s.add(m);
456	  for (const d of ["metformin", "insulin", "allopurinol", "penicillin", "amoxicillin", "sulfamethoxazole", "trimethoprim", "codeine", "morphine", "lithium", "spironolactone"]) s.add(d);
457	  return [...s].sort((a, b) => b.length - a.length);
