460	interface DrugDx {
461	  substance: string;
462	  classMembers?: string[];
463	  conditionNamed: boolean;
464	}
465	
466	/** Recognise a diagnosis the source attributes to a drug. */
467	function drugCausedDx(desc: string, icd: string | undefined): DrugDx | null {
468	  const d = desc.toLowerCase();
469	  const tCode = !!icd && /^T(3[6-9]|4\d|50)\.[0-9A-Z]{1,2}5/i.test(icd.replace(/X/gi, "X"));
470	  const attributes = /(associated|induced|related|due to|caused by|secondary to|adverse effect|reaction to|from)\b/.test(d);
471	  if (!tCode && !attributes) return null;
472	  let substance: string | undefined;
473	  let classMembers: string[] | undefined;
474	  for (const c of DRUG_CLASSES) {
475	    if (c.re.test(desc)) { substance = c.label; classMembers = c.members; break; }
476	  }
477	  // A specific drug named in the description wins over a class.
478	  for (const name of KNOWN_DRUGS) {
479	    if (new RegExp(`\\b${name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "i").test(d)) { substance = name; classMembers = undefined; break; }
480	  }
481	  if (!substance) {
482	    if (!tCode) return null;
483	    const m = /adverse effect of ([^,;()]+)/i.exec(desc);
484	    if (!m) return null;
485	    substance = m[1].trim().replace(/,? (initial|subsequent) encounter.*$/i, "").trim();
486	    if (!substance) return null;
487	  }
488	  const conditionNamed = !/^\s*adverse effect of\b/i.test(desc) && !(tCode && /^\s*(adverse|side) effect/i.test(desc));
489	  return { substance, classMembers, conditionNamed };
490	}
