501	function buildProblems(evs: Ev[]): { lines: ProbLine[] } {
502	  const lines: ProbLine[] = [];
503	  for (const [, events] of groupBy(evs, "problem_id")) {
504	    const valid = events.filter((ev) => ["add", "update", "resolve", "remove"].includes(ev.e.action));
505	    if (valid.length === 0) continue;
506	    let status: "active" | "resolved" | "removed" = "active";
507	    for (const ev of valid) {
508	      if (ev.e.action === "add") status = "active";
509	      else if (ev.e.action === "resolve") status = "resolved";
510	      else if (ev.e.action === "remove") status = "removed";
511	    }
512	    if (status === "removed") continue;
513	    const last = valid[valid.length - 1];
514	    // Latest wording/codes: restated on every event.
515	    let desc: string | undefined;
516	    let icd: string | undefined;
517	    let snomed: string | undefined;
518	    let onset: ProblemRow["onset"] | undefined;
519	    for (const ev of valid) {
520	      desc = str(ev.e.description) ?? desc;
521	      icd = str(ev.e.icd10cm) ?? icd;
522	      snomed = str(ev.e.snomed) ?? snomed;
523	      onset = fuzzy(ev.e.onset) ?? onset;
524	    }
525	    if (!desc && !icd) continue;
526	    const condition = desc ?? icd!;
527	    const row: ProblemRow = { condition, status, evidence: evidenceOf(valid) };
528	    if (icd) row.icd10cm = icd;
529	    if (snomed) row.snomed = snomed;
530	    if (onset) row.onset = onset;
531	    if (isCkd(condition, icd)) {
532	      const st = ckdStage(condition, icd);
533	      if (st) row.ckd_stage = st;
534	      const al = albuminuria(condition);
535	      if (al) row.albuminuria = al;
536	    }
537	    const sens = mergeSens(restrictedSens(valid), icdSensitivity(icd));
538	    if (sens) row.sensitivity = sens;
539	    const key = isCkd(condition, icd) ? "ckd" : icd ? "icd:" + icd.toUpperCase() : "desc:" + condition.toLowerCase();
540	    lines.push({ key, last, row, status, dx: drugCausedDx(condition, icd), events: valid });
541	  }
542	  return { lines };
543	}
