549	const HYPERSENS = /(hives|urticaria|rash|angioedema|swelling|anaphyla|bronchospasm|wheez|itch|prurit|throat (tight|closing)|stevens|sjs|toxic epidermal|dress\b|blister)/i;
550	const SERIOUS = /(ketoacidosis|lactic acidosis|hyperkalemia|acute kidney injury|\baki\b|pancreatitis|rhabdomyolysis|agranulocytosis|hepatotoxicity|liver injury|hypoglycemia|bleeding|hemorrhage|seizure|qt prolongation|torsade|arrhythmia)/i;
551	const ACE_INHIBITORS = new Set(DRUG_CLASSES[1].members);
552	
553	function classifyReaction(
554	  sourceType: unknown,
555	  reactionText: string,
556	  substance: string,
557	): { reaction_type: AllergyIntoleranceRow["reaction_type"]; mechanism: AllergyIntoleranceRow["mechanism"] } {
558	  const isAce = ACE_INHIBITORS.has(substance) || /ace inhibitor/i.test(substance);
559	  let reaction_type: AllergyIntoleranceRow["reaction_type"];
560	  if (HYPERSENS.test(reactionText)) reaction_type = "hypersensitivity";
561	  else if (SERIOUS.test(reactionText) || sourceType === "adverse_reaction") reaction_type = "serious_adverse_event";
562	  else if (sourceType === "allergy" && !reactionText) reaction_type = "hypersensitivity";
563	  else if (sourceType === "allergy" && !/(cough|nausea|vomit|diarr|gi upset|upset stomach|myalgia|muscle|headache|dizz|fatigue|constipation|edema|flushing|insomnia|drows)/i.test(reactionText)) reaction_type = "hypersensitivity";
564	  else reaction_type = "side_effect";
565	
566	  let mechanism: AllergyIntoleranceRow["mechanism"] = "unknown";
567	  if (isAce && /(cough|angioedema)/i.test(reactionText)) mechanism = "non_immune";
568	  else if (/ketoacidosis|lactic acidosis/i.test(reactionText)) mechanism = "non_immune";
569	  else if (sourceType === "allergy") mechanism = reaction_type === "hypersensitivity" ? "immune" : "unknown";
570	  else if (sourceType === "intolerance") mechanism = reaction_type === "side_effect" ? "non_immune" : "unknown";
571	  else if (sourceType === "adverse_reaction") mechanism = reaction_type === "serious_adverse_event" ? "non_immune" : "unknown";
572	  return { reaction_type, mechanism };
573	}
