581	function buildAllergies(evs: Ev[]): AlLine[] {
582	  const out: AlLine[] = [];
583	  for (const [, events] of groupBy(evs, "allergy_id")) {
584	    const valid = events.filter((ev) => ["add", "update", "inactivate"].includes(ev.e.action));
585	    if (valid.length === 0) continue;
586	    const last = valid[valid.length - 1];
587	    if (last.e.action === "inactivate") continue;
588	    const e = last.e;
589	    const name = str(e.substance?.name);
590	    if (!name) continue;
591	    const substance = (ingredientOf(name) ?? name).toLowerCase();
592	    const reactions: string[] = Array.isArray(e.reactions) ? e.reactions.filter((r: unknown) => typeof r === "string" && r.trim()).map((r: string) => r.trim()) : [];
593	    const reactionText = reactions.join("; ");
594	    const cls = classifyReaction(e.reaction_type, reactionText, substance);
595	    const row: AllergyIntoleranceRow = {
596	      substance,
597	      reaction_type: cls.reaction_type,
598	      mechanism: cls.mechanism,
599	      criticality: e.severity === "low" || e.severity === "high" ? e.severity : "unknown",
600	      evidence: evidenceOf(valid),
601	    };
602	    const rx = str(e.substance?.rxnorm);
603	    if (rx) row.rxnorm_ingredient = rx;
604	    if (reactionText) row.reaction = reactionText;
605	    let onset: AllergyIntoleranceRow["onset"] | undefined;
606	    for (const ev of valid) onset = fuzzy(ev.e.onset) ?? onset;
607	    if (onset) row.onset = onset;
608	    const sens = restrictedSens(valid);
609	    if (sens) row.sensitivity = sens;
610	    out.push({ key: substance, last, row });
611	  }
612	  return out;
613	}
