620	  "2160-0": "creatinine", "38483-4": "creatinine",
621	  "48642-3": "egfr", "48643-1": "egfr", "33914-3": "egfr", "62238-1": "egfr", "98979-8": "egfr", "88293-6": "egfr",
622	  "88294-4": "egfr", "50044-7": "egfr", "69405-9": "egfr", "77147-7": "egfr", "50210-4": "egfr", "98980-6": "egfr",
623	  "2823-3": "potassium", "6298-4": "potassium", "2951-2": "sodium", "2947-0": "sodium",
624	  "2075-0": "chloride", "2069-3": "chloride", "2028-9": "bicarbonate", "1963-8": "bicarbonate", "1959-6": "bicarbonate",
625	  "33037-3": "anion_gap", "41276-7": "anion_gap", "1863-0": "anion_gap", "10466-1": "anion_gap",
626	  "3094-0": "bun", "6299-2": "bun", "2345-7": "glucose", "2339-0": "glucose", "1558-6": "glucose",
627	  "4548-4": "a1c", "17856-6": "a1c", "9318-7": "uacr", "14959-1": "uacr", "32294-1": "uacr",
628	  "777-3": "platelets", "26515-7": "platelets", "6690-2": "wbc", "26464-8": "wbc", "718-7": "hemoglobin", "20509-6": "hemoglobin",
629	  "53060-9": "bhb", "47596-5": "bhb", "2744-1": "ph", "11558-4": "ph", "2019-8": "pco2", "11557-6": "pco2", "2021-4": "pco2",
