631	  "2093-3": "cholesterol", "2571-8": "triglycerides", "2085-9": "hdl", "13457-7": "ldl", "18262-6": "ldl", "2089-1": "ldl",
632	};
633	
634	const CODE_MAP: Record<string, Analyte> = {
635	  CREAT: "creatinine", K: "potassium", NA: "sodium", CL: "chloride", CO2: "bicarbonate", HCO3: "bicarbonate",
636	  TCO2: "bicarbonate", AGAP: "anion_gap", AG: "anion_gap", BUN: "bun", GLU: "glucose", GLUC: "glucose",
637	  A1C: "a1c", HBA1C: "a1c", UACR: "uacr", ACR: "uacr", PLT: "platelets", WBC: "wbc", HGB: "hemoglobin", HB: "hemoglobin",
638	  BHB: "bhb", PH: "ph", PCO2: "pco2", LIPASE: "lipase", LIP: "lipase", TROP: "troponin", TNI: "troponin", TROPI: "troponin",
639	  CHOL: "cholesterol", TC: "cholesterol", TRIG: "triglycerides", TG: "triglycerides", HDL: "hdl", LDL: "ldl", LDLC: "ldl",
640	};
641	
642	function analyteOf(test: any, resultCode: string): Analyte | null {
643	  const name = String(test?.name ?? "");
644	  const code = String(test?.nfm_code ?? "").toUpperCase();
645	  const n = name.toLowerCase();
646	  // Urine creatinine / urine glucose etc. are not the serum analytes.
647	  const urine = /\burine|\bur\b|urinary/.test(n);
648	  if (/^EGFR/.test(code) || /\begfr\b|glomerular filtration/.test(n) || /EGFR/i.test(resultCode)) return "egfr";
649	  if (/albumin\s*\/\s*creat|albumin.creatinine ratio|\buacr\b|microalb.*creat/.test(n)) return "uacr";
650	  const loinc = str(test?.loinc);
651	  if (loinc && LOINC_MAP[loinc]) {
652	    const a = LOINC_MAP[loinc];
653	    if (urine && a !== "uacr") return null;
654	    return a;
655	  }
656	  if (urine) return null;
657	  if (CODE_MAP[code]) return CODE_MAP[code];
658	  const lk = resultCode.toUpperCase().replace(/^LK-/, "");
659	  if (CODE_MAP[lk]) return CODE_MAP[lk];
660	  if (/creatinine/.test(n)) return "creatinine";
661	  if (/potassium/.test(n)) return "potassium";
662	  if (/sodium/.test(n)) return "sodium";
663	  if (/chloride/.test(n)) return "chloride";
664	  if (/anion gap/.test(n)) return "anion_gap";
665	  if (/bicarbonate|\bco2\b|carbon dioxide/.test(n) && !/pco2|partial/.test(n)) return "bicarbonate";
666	  if (/urea nitrogen|\bbun\b/.test(n)) return "bun";
667	  if (/a1c|glycated h|glycohemoglobin/.test(n)) return "a1c";
668	  if (/glucose/.test(n) && !/meter|poc|point of care|fingerstick/.test(n)) return "glucose";
669	  if (/platelet/.test(n)) return "platelets";
670	  if (/white blood|\bwbc\b|leukocyte/.test(n)) return "wbc";
671	  if (/hemoglobin|\bhgb\b/.test(n)) return "hemoglobin";
672	  if (/hydroxybutyrate|\bbhb\b/.test(n)) return "bhb";
673	  if (/\bpco2\b/.test(n)) return "pco2";
674	  if (/\bph\b/.test(n)) return "ph";
675	  if (/lipase/.test(n)) return "lipase";
676	  if (/troponin/.test(n)) return "troponin";
677	  if (/triglycer/.test(n)) return "triglycerides";
678	  if (/\bhdl\b/.test(n)) return "hdl";
679	  if (/\bldl\b/.test(n)) return "ldl";
680	  if (/cholesterol/.test(n) && !/non[- ]?hdl|vldl|ratio/.test(n)) return "cholesterol";
681	  return null;
682	}
683	
684	const UNIT_OF: Record<Analyte, string> = {
685	  creatinine: "mg/dL", egfr: "mL/min/1.73m2", potassium: "mmol/L", sodium: "mmol/L", chloride: "mmol/L",
686	  bicarbonate: "mmol/L", anion_gap: "mmol/L", bun: "mg/dL", glucose: "mg/dL", a1c: "%", uacr: "mg/g",
687	  platelets: "10*3/uL", wbc: "10*3/uL", hemoglobin: "g/dL", bhb: "mmol/L", ph: "[pH]", pco2: "mmHg",
688	  lipase: "U/L", troponin: "ng/mL", cholesterol: "mg/dL", triglycerides: "mg/dL", hdl: "mg/dL", ldl: "mg/dL",
689	};
690	
691	const normUnit = (u: string) => u.toLowerCase().replace(/\s+/g, "").replace(/µ|μ/g, "u");
692	
693	/** Factor to convert the filed unit into the consumer's unit, or null if not convertible. */
694	function unitFactor(a: Analyte, unit: string): number | null {
695	  const u = normUnit(unit);
696	  const target = normUnit(UNIT_OF[a]);
697	  if (u === target) return 1;
698	  switch (a) {
699	    case "egfr":
700	      if (/^ml\/min(\/1\.73m\^?2|\/1\.73m2|\/1\.73sqm|\/{1\.73_m2})?$/.test(u) || u === "ml/min/1.73m²") return 1;
701	      return null;
702	    case "potassium": case "sodium": case "chloride": case "bicarbonate": case "anion_gap": case "bhb":
703	      return u === "meq/l" || u === "mmol/l" ? 1 : null;
704	    case "platelets": case "wbc":
705	      if (u === "cells/ul" || u === "/ul" || u === "cells/mm3" || u === "/mm3") return 1 / 1000;
706	      if (u === "k/ul" || u === "10*3/ul" || u === "x10e3/ul" || u === "10^3/ul" || u === "thou/ul" || u === "x10^3/ul" || u === "10*9/l" || u === "x10e9/l" || u === "10^9/l") return 1;
707	      return null;
708	    case "ph":
709	      return u === "" || u === "[ph]" || u === "ph" ? 1 : null;
710	    case "pco2":
711	      return u === "mmhg" || u === "mm[hg]" ? 1 : null;
712	    case "lipase":
713	      return u === "u/l" || u === "iu/l" ? 1 : null;
714	    case "troponin":
715	      if (u === "ng/ml" || u === "ug/l") return 1;
716	      if (u === "ng/l" || u === "pg/ml") return 1 / 1000;
717	      return null;
718	    case "a1c":
719	      return u === "%" || u === "%hba1c" || u === "%ofhgb" || u === "%oftotalhgb" ? 1 : null;
720	    case "uacr":
721	      return u === "mg/g" || u === "mg/gcreat" || u === "mg/g{creat}" || u === "ug/mgcreat" || u === "ug/mg" ? 1 : null;
722	    case "hemoglobin":
723	      return u === "g/dl" ? 1 : null;
724	    default:
725	      return u === "mg/dl" ? 1 : null;
726	  }
727	}
728	
729	function egfrEquation(e: any): LabResultRow["egfr_equation"] {
730	  const comment = String(e.comment ?? "") + " " + String(e.test?.name ?? "");
731	  if (/ckd[- ]?epi[^.;]*2021|2021[^.;]*ckd[- ]?epi|race[- ]free/i.test(comment)) return "ckd-epi-2021";
732	  if (/ckd[- ]?epi[^.;]*2009|2009[^.;]*ckd[- ]?epi/i.test(comment)) return "ckd-epi-2009";
733	  if (/\bmdrd\b/i.test(comment)) return "mdrd";
734	  const rc = String(e.external_ref?.result_code ?? "") + " " + String(e.test?.nfm_code ?? "");
735	  if (/21/.test(rc) && /egfr/i.test(rc)) return "ckd-epi-2021";
736	  if (/09/.test(rc) && /egfr/i.test(rc)) return "ckd-epi-2009";
737	  if (/mdrd/i.test(rc)) return "mdrd";
738	  if (/ckd[- ]?epi/i.test(comment)) return "unknown";
739	  return "unknown";
740	}
741	
742	/** True for the race-coefficient variant of an eGFR (the "African American"/"Black" value). */
743	function isRaceVariant(e: any): boolean {
744	  const name = String(e.test?.name ?? "").toLowerCase();
745	  const code = String(e.test?.nfm_code ?? "").toUpperCase();
746	  const rc = String(e.external_ref?.result_code ?? "").toUpperCase();
747	  if (/non[- ]?(african|black|aa\b)/.test(name) || /NAA$|NONAA|NB$/.test(code)) return false;
748	  if (/african|black/.test(name)) return true;
749	  if (/-AA$/.test(code) || /EGFR\d*A$/.test(rc)) return true;
750	  if (e.test?.loinc === "48643-1" || e.test?.loinc === "88293-6") return true;
751	  return false;
752	}
753	
754	function buildLabs(evs: Ev[]): LabResultRow[] {
755	  interface Cand { row: LabResultRow; key: string; rank: number; rec: number }
756	  const cands: Cand[] = [];
757	  for (const ev of evs) {
758	    const e = ev.e;
759	    const raw = typeof e.value === "string" ? e.value : typeof e.value === "number" ? String(e.value) : "";
760	    const m = /^\s*(<=|>=|<|>)?\s*(-?\d+(?:\.\d+)?|-?\.\d+)\s*$/.exec(raw);
761	    if (!m) continue;
762	    const resultCode = String(e.external_ref?.result_code ?? "");
763	    const analyte = analyteOf(e.test, resultCode);
764	    if (!analyte) continue;
765	    if (analyte === "egfr" && isRaceVariant(e)) continue;
766	    const factor = unitFactor(analyte, String(e.unit ?? ""));
767	    if (factor === null) continue;
768	    let value = parseFloat(m[2]);
769	    if (!isFinite(value)) continue;
770	    if (factor !== 1) value = Math.round(value * factor * 1e6) / 1e6;
771	    const status: LabResultRow["status"] | null =
772	      e.result_status === "F" || e.result_status === "C" ? "final" : e.result_status === "P" ? "preliminary" : null;
773	    if (!status) continue;
774	    const collected = str(e.collected) ?? str(ev.item.effective);
775	    if (!collected) continue;
776	    const row: LabResultRow = { analyte, value, unit: UNIT_OF[analyte], collected, status, evidence: [{ item_id: ev.item.id, entry_id: ev.entryId }] };
777	    if (m[1]) row.comparator = m[1] as LabResultRow["comparator"];
778	    if (analyte === "egfr") row.egfr_equation = egfrEquation(e);
779	    const loinc = str(e.test?.loinc);
780	    if (loinc) row.loinc = loinc;
781	    const acc = str(e.external_ref?.accession);
782	    const comp = resultCode || String(e.test?.nfm_code ?? "");
783	    const key = acc ? `${acc}\u0000${comp}` : `${ev.item.id}\u0000${ev.entryId}`;
784	    cands.push({ row, key, rank: status === "final" ? 1 : 0, rec: isNaN(ev.rec) ? 0 : ev.rec });
785	  }
786	  const best = new Map<string, Cand>();
787	  for (const c of cands) {
788	    const cur = best.get(c.key);
789	    if (!cur || c.rank > cur.rank || (c.rank === cur.rank && c.rec > cur.rec)) best.set(c.key, c);
790	  }
791	  return [...best.values()]
792	    .map((c) => c.row)
793	    .sort((a, b) => instant(a.collected) - instant(b.collected) || (a.analyte < b.analyte ? -1 : a.analyte > b.analyte ? 1 : 0));
794	}
795	
796	// ─────────────────────────────────────────────────────────────────────────────
797	// Vitals
798	// ─────────────────────────────────────────────────────────────────────────────
799	
800	function parseBp(s: unknown): [number, number] | null {
801	  if (typeof s !== "string") return null;
802	  const m = /^\s*(\d{2,3})\s*\/\s*(\d{2,3})\s*$/.exec(s);
803	  if (!m) return null;
804	  return [parseInt(m[1], 10), parseInt(m[2], 10)];
805	}
806	
807	function buildVitals(evs: Ev[]): VitalRow[] {
808	  const rows: VitalRow[] = [];
809	  for (const ev of evs) {
810	    const e = ev.e;
811	    const t = localDateTime(ev.item.effective) ?? localDateTime(ev.item.recorded);
812	    if (!t) continue;
813	    const row: VitalRow = { setting: "clinic", local_time: t, evidence: [{ item_id: ev.item.id, entry_id: ev.entryId }] };
814	    let any = false;
815	    const bp = parseBp(e.bp);
816	    if (bp) { row.systolic_mmhg = bp[0]; row.diastolic_mmhg = bp[1]; any = true; }
817	    const rp = parseBp(e.bp_repeat);
818	    if (rp) { row.repeat_systolic_mmhg = rp[0]; row.repeat_diastolic_mmhg = rp[1]; any = true; }
819	    if (typeof e.pulse_bpm === "number" && isFinite(e.pulse_bpm)) { row.pulse_bpm = e.pulse_bpm; any = true; }
820	    if (typeof e.weight_lb === "number" && isFinite(e.weight_lb) && e.weight_lb > 0) {
821	      row.weight_kg = Math.round(e.weight_lb * 0.45359237 * 10) / 10;
822	      any = true;
823	    }
824	    if (any) rows.push(row);
825	  }
826	  return rows.sort((a, b) => (a.local_time < b.local_time ? -1 : a.local_time > b.local_time ? 1 : 0));
827	}
828	
829	// ─────────────────────────────────────────────────────────────────────────────
830	// Entry point
831	// ─────────────────────────────────────────────────────────────────────────────
832	
833	export function transform(items: FolioItem[], asOf: string): ViewRows {
834	  const out: ViewRows = { medications: [], problems: [], allergies: [], labs: [], vitals: [] };
835	  if (!Array.isArray(items) || typeof asOf !== "string") return out;
836	  const cur = currentItems(items, asOf.trim().slice(0, 10));
837	  const byType = collect(cur);
838	  const get = (t: string) => byType.get(t) ?? [];
839	
840	  let ingredientsByItem = new Map<string, string[]>();
841	  try {
842	    const med = buildMedications(get("med_event"));
843	    out.medications = med.rows;
844	    ingredientsByItem = med.ingredientsByItem;
845	  } catch { /* skip unreadable */ }
846	
847	  let allergyLines: AlLine[] = [];
848	  try { allergyLines = buildAllergies(get("allergy_event")); } catch { /* skip */ }
849	
850	  try {
851	    const { lines } = buildProblems(get("problem_event"));
852	    // One problem row per condition: latest line wins, evidence merged.
853	    const best = new Map<string, ProbLine>();
854	    const allEv = new Map<string, Ev[]>();
855	    for (const l of lines) {
856	      if (l.dx && !l.dx.conditionNamed) continue; // T-code naming only the adverse effect: allergy row only
857	      const c = best.get(l.key);
858	      if (!c || cmpEv(c.last, l.last) < 0) best.set(l.key, l);
859	      allEv.set(l.key, [...(allEv.get(l.key) ?? []), ...l.events]);
860	    }
861	    for (const [k, l] of best) {
862	      const evs = (allEv.get(k) ?? l.events).slice().sort(cmpEv);
863	      // Cite the current line first.
864	      l.row.evidence = evidenceOf([...l.events.slice().reverse(), ...evs.slice().reverse()]);
865	      out.problems.push(l.row);
866	    }
867	    out.problems.sort((a, b) => (a.condition < b.condition ? -1 : a.condition > b.condition ? 1 : 0));
868	
869	    // Drug-caused diagnoses yield an allergy row too.
870	    for (const l of lines) {
871	      if (!l.dx) continue;
872	      let substance = l.dx.substance;
873	      if (l.dx.classMembers) {
874	        const inItem = new Set<string>();
875	        for (const ev of l.events) for (const ing of ingredientsByItem.get(ev.item.id) ?? []) if (l.dx.classMembers.includes(ing)) inItem.add(ing);
876	        if (inItem.size === 1) substance = [...inItem][0];
877	      }
878	      const cond = l.row.condition;
879	      const cls = classifyReaction("adverse_reaction", cond, substance);
880	      const row: AllergyIntoleranceRow = {
881	        substance,
882	        reaction_type: cls.reaction_type,
883	        mechanism: l.dx.conditionNamed ? cls.mechanism : "unknown",
884	        criticality: "unknown",
885	        evidence: evidenceOf(l.events.slice().reverse()),
886	      };
887	      if (l.dx.conditionNamed) row.reaction = cond;
888	      if (l.row.onset) row.onset = l.row.onset;
889	      if (l.row.sensitivity) row.sensitivity = l.row.sensitivity;
890	      allergyLines.push({ key: substance.toLowerCase(), last: l.last, row });
891	    }
892	  } catch { /* skip */ }
893	
894	  // One allergy row per substance: an allergy-list line wins over a derived row; evidence merged.
895	  const byKey = new Map<string, AlLine[]>();
896	  for (const a of allergyLines) byKey.set(a.key, [...(byKey.get(a.key) ?? []), a]);
897	  for (const [, group] of byKey) {
898	    let chosen = group[0];
899	    for (const g of group) if (cmpEv(chosen.last, g.last) < 0) chosen = g;
900	    const listLines = group.filter((g) => g.last.e.type === "allergy_event");
901	    if (listLines.length) {
902	      chosen = listLines[0];
903	      for (const g of listLines) if (cmpEv(chosen.last, g.last) < 0) chosen = g;
904	    }
905	    const ev: Evidence = [...chosen.row.evidence];
906	    for (const g of group) for (const x of g.row.evidence) if (!ev.some((y) => y.item_id === x.item_id && y.entry_id === x.entry_id)) ev.push(x);
907	    out.allergies.push({ ...chosen.row, evidence: ev });
908	  }
909	  out.allergies.sort((a, b) => (a.substance < b.substance ? -1 : a.substance > b.substance ? 1 : 0));
910	
911	  try { out.labs = buildLabs(get("imported_result")); } catch { /* skip */ }
912	  try { out.vitals = buildVitals(get("vital_set")); } catch { /* skip */ }
913	  return out;
914	}
